def min_recolors_to_nice_garland(n, s):
    def check_color(color):
        indices = [i for i, c in enumerate(s) if c == color]
        return len(indices) % 3 == 0

    def find_next_color(index):
        next_index = (index + 1) % n
        while s[next_index] == s[index]:
            next_index = (next_index + 1) % n
        return next_index

    def recolor_to_color(start, target_color):
        count = 0
        current = start
        while True:
            if s[current] != target_color:
                s[current] = target_color
                count += 1
            next_current = find_next_color(current)
            if next_current == start:
                break
            current = next_current
        return count

    # Check if the garland is already nice
    if all(check_color('R') and check_color('G') and check_color('B')):
        return 0, ''.join(s)

    # Try to recolor to 'R', 'G', and 'B' separately and find the minimum
    results = []
    for target_color in ['R', 'G', 'B']:
        temp_s = list(s)
        count = recolor_to_color(0, target_color)
        if check_color(target_color):
            results.append((count, ''.join(temp_s)))

    # Return the result with the minimum number of recolors
    min_count, min_result = min(results, key=lambda x: x[0])
    return min_count, min_result

