def min_recolors_to_nice_garland(n, s):
    def can_be_nice(color_map):
        for color in color_map:
            positions = [i for i, c in enumerate(s) if c == color]
            if not positions:
                continue
            diff = abs(positions[1] - positions[0])
            if any(abs(pos1 - pos2) % 3 != diff for pos1, pos2 in zip(positions, positions[1:])):
                return False
        return True

    color_map = {'R': [], 'G': [], 'B': []}
    for i, char in enumerate(s):
        color_map[char].append(i)

    if can_be_nice(color_map):
        return 0, s

    changes_needed = float('inf')
    best_garland = None

    for r in range(3):
        new_color_map = {'R': [], 'G': [], 'B': []}
        for color in ['R', 'G', 'B']:
            if color != chr(ord('R') + r):
                for pos in color_map[color]:
                    new_color_map['R'].append(pos)
            else:
                for pos in color_map[color]:
                    new_color_map['G'].append(pos)
        if can_be_nice(new_color_map):
            changes = sum(len(v) for v in color_map.values()) - sum(len(v) for v in new_color_map.values())
            if changes < changes_needed:
                changes_needed = changes
                best_garland = ''.join(['RGB'[ord(c) - ord('R')] for c in s])

    return changes_needed, best_garland

